package org.rhetos.arn

import kotlinx.browser.document
import kotlinx.browser.window
import kotlinx.coroutines.MainScope
import kotlinx.coroutines.await
import kotlinx.coroutines.launch
import kotlinx.serialization.json.Json
import org.rhetos.arn.json.LJE
import org.w3c.dom.HTMLAnchorElement

class YoungE(private val id: Int) {

    private val scope = MainScope()

    fun main() {
        scope.launch {
            val response = window.fetch("jsonData/lje.json").await()
            val json = response.text().await()
            val lje = Json.decodeFromString<List<LJE>>(json)

            val currentLje = lje.find { it.id == id }

            if (currentLje == null) {
                NotFound().main()
                return@launch
            }

            document.title = currentLje.name

            val container = document.getElementById("current-lje")!!

            val title = document.createElement("h1")
            title.textContent = currentLje.name

            val logo = document.createElement("img")
            logo.setAttribute("src", currentLje.file)
            logo.setAttribute("display", "block")
            logo.setAttribute("width", "50%")
            logo.setAttribute("style", "display: block; margin: 0 auto;")

            val link = document.createElement("a") as HTMLAnchorElement
            link.textContent = "(" + currentLje.url + ")"
            link.href = currentLje.url
            link.target = "_blank"

            val contact = document.createElement("p")
            contact.textContent = "contact: " + currentLje.contact

            val description = document.createElement("h2")
            description.textContent = currentLje.description

            val authors = document.createElement("h5")
            authors.textContent = currentLje.authors.joinToString(separator = ", ")

            val subDescription = document.createElement("p")
            subDescription.textContent = currentLje.long

            container.appendChild(title)
            container.appendChild(logo)
            container.appendChild(link)
            container.appendChild(contact)
            container.appendChild(description)
            container.appendChild(authors)
            container.appendChild(subDescription)
        }
    }
}