package org.rhetos.arn

import kotlinx.browser.window
import kotlinx.browser.document
import kotlinx.coroutines.MainScope
import kotlinx.coroutines.await
import kotlinx.coroutines.launch
import kotlinx.serialization.json.Json
import org.rhetos.arn.json.Event

class EventPage(private val id: Int)  {
    private val scope = MainScope()
    fun main() {
        scope.launch {
            val response = window.fetch("jsonData/events.json").await()
            val json = response.text().await()
            val events = Json.decodeFromString<List<Event>>(json)

            val event = events.find { it.id == id }
            if (event == null) {
                NotFound().main()
                return@launch
            }

            document.title = event.name

            val container = document.getElementById("event")!!

            val title = document.createElement("h1")
            title.textContent = event.name

            val shortDescription = document.createElement("h2")
            shortDescription.textContent = event.short

            val date = document.createElement("p")
            date.textContent = event.date

            val longDescription = document.createElement("p")
            longDescription.textContent = event.long

            //media est encore à configurer

            container.appendChild(title)
            container.appendChild(shortDescription)
            container.appendChild(date)
            container.appendChild(longDescription)
        }
    }
}