package org.rhetos.arn

import kotlinx.browser.window
import org.w3c.dom.url.URLSearchParams

fun main() {
    val path = window.location.pathname //.removePrefix("/Rhetos2627-web")
    when (path) {
        "/" -> Index().main()
        "/html/comity" -> Comity().main()
        "/html/pictures" -> Pictures().main()
        "/html/events" -> Events().main()
        "/html/news" -> NewsPage().main()
        "/html/lje" -> LJEList().main()

        "/html/article" -> {
            val id = URLSearchParams(window.location.search).get("id")?.toIntOrNull()

            if (id != null) {
                Article(id).main()
            } else {
                NotFound().main()
            }
        }

        "/html/young-e" -> {
            val id = URLSearchParams(window.location.search).get("id")?.toIntOrNull()

            if (id != null) {
                YoungE(id).main()
            } else {
                NotFound().main()
            }
        }

        "/html/event" -> {
            val id = URLSearchParams(window.location.search).get("id")?.toIntOrNull()

            if (id != null) {
                EventPage(id).main()
            } else {
                NotFound().main()
            }
        }

        else -> NotFound().main()
    }
}